22	// The standalone-passthrough spine shared by `fast` and `accurate`: both take a
23	// single ELF, then exec the resolved engine standalone with the post-`--` args
24	// appended verbatim (inherit stdio, no timeout, propagate exit code). The only
25	// per-model differences -- which engine, and how it is selected -- are resolved
26	// by the caller; `model` here only labels the positional diagnostics.
27	int run_standalone(const Cli& cli, const EngineDescriptor& eng,
28	                   const char* model) {
29	  if (cli.positional.empty()) {
30	    std::fprintf(stderr, "andes-sim run --model %s: missing ELF\n", model);
31	    return 2;
32	  }
33	  if (cli.positional.size() > 1) {
34	    std::fprintf(stderr,
35	                 "andes-sim run --model %s: unexpected argument '%s' "
36	                 "(engine args go after --)\n",
37	                 model, cli.positional[1].c_str());
38	    return 2;
39	  }
40	  std::string err;
41	  int rc = run_passthrough(eng, "standalone", cli.positional[0],
42	                           cli.passthrough, err);
43	  if (!err.empty()) std::fprintf(stderr, "andes-sim run: %s\n", err.c_str());
44	  return rc;
45	}
