83	int cmd_run(const Cli& cli) {
84	  if (cli.model.empty()) {
85	    std::fprintf(stderr,
86	                 "andes-sim run: --model fast|accurate|hybrid is required\n");
87	    return 2;
88	  }
89	  if (!find_model(cli.model)) {
90	    std::fprintf(stderr,
91	                 "andes-sim run: unknown model '%s' (want fast|accurate|hybrid)\n",
92	                 cli.model.c_str());
93	    return 2;
94	  }
95	  if (cli.model == "fast") return run_fast(cli);
96	  if (cli.model == "accurate") return run_accurate(cli);
97	
98	  std::fprintf(stderr, "andes-sim run --model %s: not yet implemented\n",
99	               cli.model.c_str());
100	  return 3;
101	}
